"""Read and write dblock.lock (TOML)."""

from __future__ import annotations

import os
import tomllib
from dataclasses import asdict, dataclass, field, fields
from pathlib import Path

from dblock.recipes import Recipe, Release

LOCK_VERSION = 1
HEADER = (
    "# dblock lockfile: exact reference database releases used by this analysis.\n"
    "# Generated by dblock. Commit it with your code; edit with `dblock add/remove/fetch`.\n"
)


class LockError(Exception):
    pass


@dataclass
class Entry:
    name: str
    release: str
    recipe_digest: str
    filename: str
    format: str
    urls: list[str] = field(default_factory=list)
    upstream_checksum: str = ""
    tool: str = ""
    tool_versions: str = ""
    # Filled by `dblock fetch`:
    archive_sha256: str = ""
    checksum_origin: str = ""  # "upstream-verified" or "first-download"
    tree_digest: str = ""
    files: int = 0
    bytes: int = 0
    fetched_at: str = ""

    @property
    def fetched(self) -> bool:
        return bool(self.tree_digest)

    @classmethod
    def from_recipe(cls, recipe: Recipe, release: Release) -> "Entry":
        return cls(
            name=recipe.name,
            release=release.version,
            recipe_digest=recipe.digest,
            filename=release.filename,
            format=release.format,
            urls=list(release.urls),
            upstream_checksum=release.checksum,
            tool=recipe.tool,
            tool_versions=release.tool_versions,
        )


@dataclass
class Lockfile:
    path: Path
    entries: dict[str, Entry] = field(default_factory=dict)

    @classmethod
    def load(cls, path: str | Path, must_exist: bool = True) -> "Lockfile":
        path = Path(path)
        if not path.exists():
            if must_exist:
                raise LockError(f"lockfile not found: {path} (create one with `dblock add NAME@RELEASE`)")
            return cls(path)
        try:
            data = tomllib.loads(path.read_text(encoding="utf-8"))
        except tomllib.TOMLDecodeError as exc:
            raise LockError(f"{path}: invalid TOML: {exc}") from exc
        if data.get("lock_version") != LOCK_VERSION:
            raise LockError(f"{path}: unsupported lock_version {data.get('lock_version')!r}")
        known = {f.name for f in fields(Entry)}
        entries = {}
        for name, raw in data.get("databases", {}).items():
            unknown = set(raw) - known
            if unknown:
                raise LockError(f"{path}: unknown keys for '{name}': {sorted(unknown)}")
            entries[name] = Entry(name=name, **{k: v for k, v in raw.items() if k != "name"})
        return cls(path, entries)

    def save(self) -> None:
        lines = [HEADER, f"lock_version = {LOCK_VERSION}\n"]
        for name in sorted(self.entries):
            entry = asdict(self.entries[name])
            entry.pop("name")
            lines.append(f"\n[databases.{_key(name)}]\n")
            for key, value in entry.items():
                lines.append(f"{key} = {_value(value)}\n")
        tmp = self.path.with_name(self.path.name + ".tmp")
        tmp.write_text("".join(lines), encoding="utf-8")
        os.replace(tmp, self.path)

    def get(self, name: str) -> Entry:
        try:
            return self.entries[name]
        except KeyError:
            raise LockError(f"'{name}' is not in {self.path}") from None

    def select(self, names: list[str] | None) -> list[Entry]:
        if not names:
            return [self.entries[n] for n in sorted(self.entries)]
        return [self.get(n) for n in names]


def _key(name: str) -> str:
    if name.replace("-", "").replace("_", "").isalnum():
        return name
    return _string(name)


def _string(text: str) -> str:
    escaped = text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
    return f'"{escaped}"'


def _value(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, str):
        return _string(value)
    if isinstance(value, list):
        return "[" + ", ".join(_value(v) for v in value) + "]"
    raise TypeError(f"cannot write {type(value).__name__} to TOML")
